 if(action==='next-day'){const w=day.next_day_due.find(w=>!pending.some(p=>p.path===`/api/workouts/${w.id}/next-day-checkin`));await enqueue(`/api/workouts/${w.id}/next-day-checkin`,{checkin:clone(nd)},{workoutId:w.id,needsRevision:true});day.next_day_due=day.next_day_due.slice(1);nd={};await saveDrafts();render();toast('Ответ сохранён на устройстве');return}
 if(['weight-toggle','weight-progress'].includes(action)){weightOpen=!weightOpen;weight=Number(fromKg(progress?.weight?.current_kg||70).toFixed(1));render();return}
