 if(action==='history-detail'){detail=navigator.onLine?await request(config,`/api/history/${el.dataset.id}`):await store.get('detail:'+el.dataset.id);if(!detail)throw new Error('Это занятие ещё не загружено на устройство');await store.set('detail:'+el.dataset.id,detail);await store.set('last-detail',el.dataset.id);go('detail');return}
