async function configurePush(kind){if(!('serviceWorker'in navigator)||!('PushManager'in window))throw new Error('Push недоступен. На iPhone откройте установленное приложение.');const permission=await Notification.requestPermission();if(permission!=='granted')throw new Error('Разрешение на уведомления не получено');const registration=await navigator.serviceWorker.ready;const raw=atob(pushConfig.public_key.replace(/-/g,'+').replace(/_/g,'/')),key=Uint8Array.from(raw,c=>c.charCodeAt(0));const sub=await registration.pushManager.getSubscription()||await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});const next={next_day:!!prefs.next_day,review:!!prefs.review,[kind]:!prefs[kind]};await request(config,'/api/push/subscription',{method:'POST',body:{subscription:sub.toJSON(),preferences:next}});Object.assign(prefs,next);localStorage.setItem('gym.preferences',JSON.stringify(prefs));render()}
document.addEventListener('click', async event => {
 const el=event.target.closest('[data-action]');
 if(!el || el.disabled || busy) return;
 busy=true;
 try {
  const readActions=['today','history','progress','program','review','settings','blocked','sheet-close','take-over','sync','tech','session','history-detail'];
  if(!readActions.includes(el.dataset.action) && lease && !(await lease.acquire())) {
   sheet={kind:'other-tab'}; return;
  }
  await handle(el.dataset.action,el);
 } catch(e) { error=e.message; }
 finally { busy=false; render(); }
});
document.addEventListener('input',async event=>{const el=event.target,key=el.dataset.field;if(!key||key.startsWith('config.'))return;if(lease&&!(await lease.acquire())){sheet={kind:'other-tab'};render();return}const value=el.type==='checkbox'?el.checked:['number','range'].includes(el.type)?(el.value===''?null:Number(el.value)):el.value;pathSet(key,value);try{await saveDrafts();if(el.tagName!=='TEXTAREA')render()}catch{error='Не удалось сохранить черновик на устройстве';render()}});
